  const produits = global.KoreiProducts;
  if (produits && Array.isArray(produits.PRODUCTS)) {
    const connus = new Set(produits.PRODUCTS.map((p) => p.id));
    const ajouts = BIENTOT.filter((p) => !connus.has(p.id)).map((p) => ({
      ...p,
      notes: [...p.notesTop, ...p.notesHeart, ...p.notesBase],
      shopifyHandle: p.id,
      affiliateUrl: null,
      // Ces entrees ne passent pas par createProduct : on pose ici les
      // champs qu'il aurait deduits, pour qu'aucun ne reste indefini.
      photoManquante: !p.image,
      // Sans prix, pas de tranche de prix : le filtre du catalogue
      // les ecarte, ce qui est correct — on ne peut pas ranger dans
      // « moins de 10 EUR » un parfum dont on ignore le prix.
      priceRange: p.price ? (p.price <= 10 ? "budget" : p.price <= 14 ? "mid" : "premium") : null,
      imageWidth: p.imageWidth || (p.image ? 750 : 0),
    }));
    produits.PRODUCTS = [...produits.PRODUCTS, ...ajouts];
    if (Array.isArray(produits.CATALOGUE_COMPLET)) {
      produits.CATALOGUE_COMPLET = [...produits.CATALOGUE_COMPLET, ...ajouts];
    }
  }

  global.KoreiBientot = BIENTOT;
